import {readFileSync,writeFileSync} from 'node:fs';
import {dirname,resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {reviewCapture,reviewDigest,authorReviewStatus} from './sealed-runtime/dist-scripts/bench/entity-extraction-review.js';
import {parseEntityReviewCorpus,entityReviewInput} from './sealed-runtime/dist-scripts/bench/entity-review-corpus.js';
import {checkWindowExtractionResponse} from './sealed-runtime/dist/observability/knowledge-extraction/window-proposals.js';
const root=dirname(fileURLToPath(import.meta.url));
const load=p=>JSON.parse(readFileSync(resolve(root,p),'utf8'));
const execution=load('captures-pilot/manifest.json');
if(execution.status!=='captured'||execution.recorded!==11||execution.attempted!==11||execution.maxCalls!==11||execution.repeats!==1)throw Error('Diagnostic capture incomplete or out of plan.');
const manifest=load('frozen/manifest.json');
const corpus=parseEntityReviewCorpus(readFileSync(resolve(root,'frozen/corpus.json'),'utf8'));
authorReviewStatus(readFileSync(resolve(root,'frozen/self-review.json'),'utf8'),corpus,manifest.measurementId,execution.startedAt);
const splitResults=['development','validation'].map(split=>reviewCapture(readFileSync(resolve(root,`captures-pilot/${split}.json`),'utf8'),corpus,manifest.measurementId,checkWindowExtractionResponse));
const records=splitResults.flatMap(result=>result.records).map(record=>{
 const raw=load(`captures-pilot/1-${record.caseId}.json`);
 const runtimeText=readFileSync(resolve(root,`captures-pilot/1-${record.caseId}.runtime.json`),'utf8');
 const runtime=JSON.parse(runtimeText);
 const sample=corpus.cases.find(sample=>sample.caseId===record.caseId);
 const checked=raw.result.captureStatus==='output'?checkWindowExtractionResponse(JSON.parse(raw.result.output),entityReviewInput(sample).excerpts):null;
 return {...record,checked,outputDigest:raw.result.captureStatus==='output'?reviewDigest(raw.result.output):null,runtimeDigest:reviewDigest(runtimeText),
 executorReported:Object.fromEntries(['ok','inputTokens','outputTokens','cacheReadTokens','costReportedByExecutor','stopReason','numTurns','fullNumTurns','numSubAgents'].map(key=>[key,runtime[key]])),
 timing:{callStartedAt:raw.callStartedAt,finishedAt:raw.finishedAt,wallClockDurationMs:raw.wallClockDurationMs}};
});
const selected=corpus.cases.filter(sample=>execution.selectedCaseIds.includes(sample.caseId));
if(records.length!==11||new Set(records.map(record=>record.caseId)).size!==11||records.some(record=>!execution.selectedCaseIds.includes(record.caseId)))throw Error('Record selection mismatch.');
const sum=read=>records.reduce((n,record)=>n+read(record),0);
const statistics={selectedWindows:11,fullCorpusWindows:36,notSelectedWindows:25,repeats:1,
 plannedCriticalMentions:selected.reduce((n,sample)=>n+sample.mentions.length,0),
 matchedCriticalMentions:sum(record=>record.checks?.criticalMentions.filter(x=>x.status==='matched').length??0),
 missingCriticalMentions:sum(record=>record.checks?.criticalMentions.filter(x=>x.status!=='matched').length??0),
 wrongMerges:sum(record=>record.checks?.identityPairs.filter(x=>x.status==='wrong_merge').length??0),
 wrongSplits:sum(record=>record.checks?.identityPairs.filter(x=>x.status==='wrong_split').length??0),
 notEvaluableIdentityPairs:sum(record=>record.checks?.identityPairs.filter(x=>x.status==='not_evaluable').length??0),
 identityMismatches:sum(record=>record.checks?.identities.filter(x=>x.status==='mismatched').length??0),
 structuralRejectingOutputs:records.filter(record=>record.structuralRejections.length).length,
 acceptedEntities:sum(record=>record.checked?.analysis.entities.length??0),acceptedMentions:sum(record=>record.checked?.analysis.mentions.length??0),
 acceptedKnowledgeCandidates:sum(record=>record.checked?.accepted.length??0),
 reportedUncachedInputTokens:sum(record=>record.executorReported.inputTokens??0),reportedCacheReadTokens:sum(record=>record.executorReported.cacheReadTokens??0),reportedOutputTokens:sum(record=>record.executorReported.outputTokens??0),
 usdCost:'unknown',reportedCostUSD:null,wallClockDurationMs:Date.parse(execution.finishedAt)-Date.parse(execution.startedAt)};
const result={manifest,execution,splitSummaries:splitResults.map(result=>({split:result.capture.split,...result.summary})),records,statistics};
writeFileSync(resolve(root,'pilot-check.json'),JSON.stringify(result,null,2),{flag:'wx'});
console.log(JSON.stringify(statistics,null,2));
